import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface Transaction {
  id: string;
  userId: string;
  type: 'credit' | 'debit' | 'transfer' | 'pix' | 'payment';
  amount: number;
  description?: string;
  createdAt: string; // ISO date string
  status?: 'pending' | 'completed' | 'failed';
  metadata?: Record<string, unknown>;
}

export interface CreateTransactionPayload {
  type: Transaction['type'];
  amount: number;
  description?: string;
  toUserId?: string; // for transfers
  metadata?: Record<string, unknown>;
}

export interface PaginatedResult<T> {
  items: T[];
  total: number;
  page: number;
  pageSize: number;
}

@Injectable({ providedIn: 'root' })
export class TransactionService {
  // Adjust to your backend base URL
  private readonly baseUrl = '/api';

  constructor(private http: HttpClient) {}

  // List all transactions (admin or scoped by query)
  list(params?: { page?: number; pageSize?: number; type?: Transaction['type']; userId?: string; status?: Transaction['status'] }): Observable<PaginatedResult<Transaction>> {
    return this.http.get<PaginatedResult<Transaction>>(`${this.baseUrl}/transactions`, { params: (params as any) });
  }

  // Get a single transaction by id
  getById(id: string): Observable<Transaction> {
    return this.http.get<Transaction>(`${this.baseUrl}/transactions/${id}`);
  }

  // Create a new transaction (requires auth)
  create(payload: CreateTransactionPayload, token?: string): Observable<Transaction> {
    const headers = token ? new HttpHeaders({ Authorization: `Bearer ${token}` }) : undefined;
    return this.http.post<Transaction>(`${this.baseUrl}/transactions`, payload, { headers });
  }

  // List transactions for the current authenticated user via token
  listMy(token: string, params?: { page?: number; pageSize?: number; type?: Transaction['type']; status?: Transaction['status'] }): Observable<PaginatedResult<Transaction>> {
    const headers = new HttpHeaders({ Authorization: `Bearer ${token}` });
    return this.http.get<PaginatedResult<Transaction>>(`${this.baseUrl}/users/me/transactions`, { headers, params: (params as any) });
  }

  // List transactions by a specific user id (admin or trusted route)
  listByUserId(userId: string, params?: { page?: number; pageSize?: number; type?: Transaction['type']; status?: Transaction['status'] }): Observable<PaginatedResult<Transaction>> {
    return this.http.get<PaginatedResult<Transaction>>(`${this.baseUrl}/users/${userId}/transactions`, { params: (params as any) });
  }
}
